<?php declare(strict_types=1);
$payEntry=$finance->entry($link['source_id']);if($payEntry['kind']!=='expense')return;
$payReports=new \Kulturhus\Verein\InvoicePaymentReports($db,(string)$_SESSION['actor']);$payReport=$payReports->summary($payEntry['id']);$payCanWrite=$finance->canWrite();
$payForm=\Kulturhus\Verein\Web\InvoicePaymentForm::prepare($payEntry,$payReport,$inboxId,$_POST,$payCanWrite,$_GET);
$payText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\InvoicePaymentMessages::text($s,$managerLanguageMessages??\Kulturhus\Native\Language\InvoicePaymentMessages::messages('de'),$v);
$payReceipt=['view'=>'finance','tab'=>'receipts','entry'=>$payEntry['id']];$payMatch=$payReceipt+['payment_match'=>'1']+array_intersect_key($_GET,array_flip(['match_account','match_q']));$payDraft=$payForm['report_draft'];$payWithdrawDraft=$payForm['withdraw_draft'];
?>
<link rel="stylesheet" href="invoice-payment-report.css?v=1">
<section class="card invoice-payment-workspace" id="<?=e(count($inboxSelected['entry_links']??[$link])===1?'invoice-payment':'invoice-payment-'.$payEntry['id'])?>" data-invoice-payment-entry="<?=e($payEntry['id'])?>"><h3><?=e($payText('Zahlung und Kontozuordnung'))?></h3>
<dl class="invoice-payment-totals"><dt><?=e($payText('Rechnungsbetrag'))?></dt><dd><?=e(euro((int)$payEntry['amount_cents']))?></dd><dt><?=e($payText('Kontoumsätzen zugeordnet'))?></dt><dd><?=e(euro((int)$payEntry['allocated_cents']))?></dd><dt><?=e($payText('Noch zuzuordnen'))?></dt><dd><?=e(euro((int)$payEntry['remaining_cents']))?></dd></dl>
<?php if($payReport['state']==='reported'):?><p role="status"><strong><?=e($payText('Als bezahlt gemeldet – Kontozuordnung offen'))?></strong><br><?=e($payText('Zahlungsdatum'))?> <?=e(dateDe($payReport['latest']['paid_on']))?> · <span data-invoice-payment-current-note><?=e($payReport['latest']['note'])?></span></p><?php elseif($payReport['state']==='resolved'):?><p><strong><?=e($payText('Die gemeldete Zahlung ist vollständig Kontoumsätzen zugeordnet.'))?></strong></p><?php elseif($payReport['state']==='withdrawn'):?><p role="status"><strong><?=e($payText('Zahlungsmeldung zurückgenommen'))?></strong></p><?php elseif($payReport['state']==='inactive'):?><p role="status"><?=e($payText('Die frühere Zahlungsmeldung gehört zu einem geschlossenen Beleg. Sie bestätigt keine aktuelle Zahlung.'))?></p><?php else:?><p><?=e($payText('Keine vorläufige Zahlungsmeldung gespeichert.'))?></p><?php endif;?>
<?php if($payForm['submitted']):?><section class="card invoice-payment-original" data-invoice-payment-original><h4><?=e($payText('Zahlungsangaben prüfen'))?></h4><p><?=e($payText('Die ursprüngliche Auswahl bleibt erhalten. Es wurde kein aktuellerer Stand und kein anderer Vorgang zur Bestätigung eingesetzt.'))?></p>
<dl><?php foreach($payForm['raw']as$field=>$value):?><dt><?=e($payText(\Kulturhus\Native\Language\InvoicePaymentMessages::FIELDS[$field]))?></dt><dd data-invoice-payment-raw="<?=e($field)?>"><pre><?=e(is_string($value)?$value:json_encode($value,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR))?></pre></dd><?php endforeach;?></dl>
<?php if($payForm['first']):$payFirst=$payForm['first'];?><h5><?=e($payText('Früher gespeicherte Meldung dieses Vorgangs'))?></h5><p><?=e($payText($payFirst['operation']==='reported'?'Als bezahlt gemeldet':'Meldung zurückgenommen'))?> · <?=e($payFirst['created_at'])?></p><p data-invoice-payment-first-note><?=e($payFirst['note'])?></p><p><?=e($payText('Dieser frühere Ausgang bestätigt keine neuen oder geänderten Angaben.'))?></p><?php endif;?>
<?php if($payForm['blocked']):?><p role="alert"><?=e($payText('Rechnung, Meldungsstand oder Bearbeitungsrecht passen nicht mehr zu dieser ursprünglichen Aktion. Den aktuellen Stand derselben Rechnung gesondert lesen.'))?></p><a class="btn btn-outline theme-secondary" data-invoice-payment-refresh href="<?=e(url($payForm['refresh']+['inbox_read'=>bin2hex(random_bytes(8))]))?>"><?=e($payText('Dieselbe Rechnung und Zahlungsmeldung im aktuellen Stand lesen'))?></a><?php endif;?></section><?php endif;?>
<?php if($payForm['action']==='invoice-payment-allocate'&&is_string($_POST['transaction_id']??null)):?><p><a class="btn btn-outline theme-secondary" data-invoice-payment-original-transaction target="_blank" rel="noopener" href="<?=e(url($payMatch+['candidate'=>$_POST['transaction_id']]))?>"><?=e($payText('Ursprünglichen Kontoumsatz am Beleg lesen'))?></a></p><?php endif;?>
<p><a class="btn btn-outline theme-secondary" data-invoice-payment-receipt target="_blank" rel="noopener" href="<?=e(url($payCanWrite?$payMatch:$payReceipt+['payment_history'=>'1']))?>"><?=e($payText($payCanWrite?'Originalprüfung und Kontozuordnung am Beleg öffnen':'Zahlungsstand am Beleg ansehen'))?></a></p>
<p><?=e($payText('Die vollständige Umsatzsuche und Seitenwahl stehen am zugeordneten Beleg. Die aktuellen Prüfungen und Zahlungsrechte gelten dort erneut. Zuordnen erzeugt keine neue Zahlung und überweist kein Geld.'))?></p>
<?php if($payCanWrite&&$payEntry['status']==='open'):?><p><a class="btn btn-outline theme-secondary" target="_blank" rel="noopener" href="<?=e(url($payReceipt+['manual_payment'=>'1']).'#manual-payment')?>"><?=e($payText('Tatsächliche Zahlung manuell erfassen'))?></a></p><p><?=e($payText('Für bereits erfolgte Zahlungen mit Nachweis, die noch nicht in der Kontoliste stehen. Betrag, Konto und tatsächliches Zahlungsdatum werden direkt zur Rechnung gespeichert.'))?></p><?php endif;?>
<?php if($payForm['report_allowed']&&!$payForm['blocked']):?><details <?=($payForm['action']==='invoice-payment-report')?'open':''?>><summary><?=e($payText('Zahlung nur vorläufig melden'))?></summary><p><?=e($payText('Diese Meldung bucht keinen Kontoumsatz und bestätigt keinen Zahlungsnachweis. Sie bleibt offen, bis eine tatsächliche Zahlung zugeordnet ist.'))?></p><form method="post" data-invoice-payment-report><?=csrf().hidden('action','invoice-payment-report').hidden('doc',$inboxId).hidden('entry_id',$payEntry['id']).hidden('entry_version',input($payDraft,'entry_version',(string)$payEntry['version'])).hidden('report_version',input($payDraft,'report_version',(string)$payReport['version'])).hidden('request_key',input($payDraft,'request_key',bin2hex(random_bytes(16))))?><label><?=e($payText('Zahlungsdatum'))?><input class="form-control" type="date" name="paid_on" max="<?=date('Y-m-d')?>" required value="<?=e(input($payDraft,'paid_on',date('Y-m-d')) )?>"></label><label><?=e($payText('Notiz zur Zahlung'))?><textarea class="form-control" name="note" maxlength="2000" required><?=e(input($payDraft,'note'))?></textarea></label><p><?=e($payText('Bis zu 1000 Zeichen. Den tatsächlich gemeldeten Vorgang beschreiben; die Meldung ist kein Zahlungsnachweis.'))?></p><button class="btn btn-solid theme-primary"><?=e($payText('Zahlung nur melden – ohne Kontobuchung'))?></button></form></details><?php endif;?>
<?php if($payReport['history']):?><details data-invoice-payment-history <?=($payForm['action']==='invoice-payment-withdraw')?'open':''?>><summary><?=e($payText('Verlauf der Zahlungsmeldungen'))?></summary><?php foreach($payReport['history']as$payEvent):?><p><?=e($payEvent['created_at'])?> · <?=e((new \Kulturhus\Verein\ActorNames($db,(string)$_SESSION['actor']))->label($payEvent['actor_id']))?> · <?=e($payText($payEvent['operation']==='reported'?'Als bezahlt gemeldet':'Meldung zurückgenommen'))?><?= $payEvent['paid_on']?' · '.e(dateDe($payEvent['paid_on'])):''?> · <span><?=e($payEvent['note'])?></span></p><?php endforeach;?>
<?php if($payForm['withdraw_allowed']&&!$payForm['blocked']):?><form method="post" data-invoice-payment-withdraw><?=csrf().hidden('action','invoice-payment-withdraw').hidden('doc',$inboxId).hidden('entry_id',$payEntry['id']).hidden('entry_version',input($payWithdrawDraft,'entry_version',(string)$payEntry['version'])).hidden('report_version',input($payWithdrawDraft,'report_version',(string)$payReport['version'])).hidden('request_key',input($payWithdrawDraft,'request_key',bin2hex(random_bytes(16))))?><label><?=e($payText('Grund für die Rücknahme'))?><textarea class="form-control" name="reason" maxlength="2000" required><?=e(input($payWithdrawDraft,'reason'))?></textarea></label><p><?=e($payText('Bis zu 1000 Zeichen. Nur die Meldung wird zurückgenommen; Kontoumsätze und Zahlungen bleiben unverändert.'))?></p><button class="btn btn-outline theme-secondary"><?=e($payText('Nur die Zahlungsmeldung zurücknehmen'))?></button></form><?php endif;?></details><?php endif;?>
</section>
